<?php declare(strict_types=1); require_once __DIR__.'/../../app/App.php'; if(Auth::platformCheck())redirect('platform.php'); $error=''; if(requestMethod()==='POST'){try{Csrf::requireValid($_POST['_csrf']??null);Auth::platformLogin(App::api(),trim((string)($_POST['email']??'')),(string)($_POST['password']??''));redirect('platform.php');}catch(Throwable $e){$error=$e->getMessage();}} App::render('admin/platform-login',['error'=>$error],'guest');